/*
 * ============================================================================
 * HOW TO ADD YOUR BUILDER TOOL
 * ============================================================================
 *
 * 1. Add entry: Copy the template below and add to END of BuilderTools array
 *
 *    {
 *      title: "Your Tool Name",
 *      description: "Brief description (avoid 'best/first/only' claims)",
 *      category: "sdk",                 // exactly ONE, see Categories in tags.js
 *      properties: ["typescript"],      // language + interface facets, see tags.js
 *      website: "https://your-tool.com",
 *      repository: "https://github.com/owner/repo",  // public source repo, OR null
 *      docs: "https://docs.url",        // docs / get-started page, OR null
 *    },
 *
 * 2. Test: Run `yarn build` (must complete without errors)
 *
 * 3. Submit: Create PR using "Add Builder Tool" template
 *
 * Notes:
 *  - title: use the project's OWN name as it styles it (e.g. lowercase `cardano-cli`,
 *    `gOuroboros`). Do NOT add descriptors or parentheticals or re-case it for uniformity.
 *  - description: one or two factual sentences, sentence case, ending with a period. No
 *    superlatives. Say what it does and how it differs from similar tools (its language /
 *    interface); do not just restate the name.
 *  - Pick ONE primary category that best describes what the tool IS.
 *  - properties = the language(s) it is written in + interface (rest/graphql/grpc/websocket).
 *  - Open source is encouraged: set `repository` to your public repo (it surfaces an
 *    "Open Source" badge + GitHub link). Hosted/closed services are welcome too, use null.
 *  - Do NOT set maintainerPick (maintainers choose those).
 *  - screenshots (optional): up to 3 images of the tool in use, for tools with a UI or visual
 *    output. Put the files in static/img/tools/screenshots/ (.png, .jpg or .webp, max 500 KB) and
 *    list them as `screenshots: [{ src: "/img/tools/screenshots/your-tool.webp", alt: "What the
 *    image shows" }]`. Leave the field out when there is nothing to show.
 *  - Categories + properties are defined in ./tags.js. All other fields are required (use null
 *    where noted).
 *
 * ============================================================================
 */

